#include <ESP32Servo.h>
#include <TFT_eSPI.h> // Библиотека для дисплея XiaoZhi AI

// --- Сервы ---
const int PIN_SERVO_1 = 13;
const int PIN_SERVO_2 = 14;
const int PIN_SERVO_3 = 25;
const int PIN_SERVO_4 = 26;

Servo servo1, servo2, servo3, servo4;
TFT_eSPI tft = TFT_eSPI();

// Базовые углы
int standAngle[4] = {90, 90, 90, 90};
int offset[4] = {0, 0, 0, 0};

// Текущая эмоция
enum Emotion { HAPPY, SAD, ANGRY, NEUTRAL };
Emotion currentEmotion = NEUTRAL;

void setup() {
Serial.begin(115200);

// Инициализация дисплея
tft.init();
tft.setRotation(1); // Зависит от ориентации экрана
tft.fillScreen(TFT_BLACK);

// Инициализация сервоприводов
servo1.attach(PIN_SERVO_1); servo2.attach(PIN_SERVO_2);
servo3.attach(PIN_SERVO_3); servo4.attach(PIN_SERVO_4);

moveToPose(90, 90, 90, 90);
delay(500);

drawEmotion(NEUTRAL); // Нейтральное выражение при старте
Serial.println("Robot Dog ready. Commands: w,a,s,d, space, e=happy, q=sad, r=angry");
}

void loop() {
if (Serial.available() > 0) {
char cmd = Serial.read();

switch (cmd) {
// --- Движение ---
case 'w': case 'W': walkForward(); break;
case 's': case 'S': walkBackward(); break;
case 'a': case 'A': turnLeft(); break;
case 'd': case 'D': turnRight(); break;
case ' ': moveToPose(90, 90, 90, 90); break;

// --- Эмоции (смена выражения лица) ---
case 'e': case 'E': // Радость
currentEmotion = HAPPY; drawEmotion(HAPPY); 
Serial.println("Emotion: Happy");
break;
case 'q': case 'Q': // Грусть
currentEmotion = SAD; drawEmotion(SAD);
Serial.println("Emotion: Sad");
break;
case 'r': case 'R': // Злость
currentEmotion = ANGRY; drawEmotion(ANGRY);
Serial.println("Emotion: Angry");
break;
}
}
}

// --- Функция отрисовки эмоций (Глаза/Рот) ---
void drawEmotion(Emotion emo) {
tft.fillScreen(TFT_BLACK); // Очистка экрана перед новой эмоцией

int centerX = tft.width() / 2;
int centerY = tft.height() / 2;

switch(emo) {
case HAPPY:
// Радость: дуги вверх (улыбка) и большие глаза
tft.fillCircle(centerX - 30, centerY, 15, TFT_WHITE);
tft.fillCircle(centerX + 30, centerY, 15, TFT_WHITE);
tft.drawArc(centerX, centerY + 20, 30, 20, 0, 180, TFT_WHITE);
break;

case SAD:
// Грусть: глаза опущены, дуга вниз (грустный рот)
tft.fillCircle(centerX - 30, centerY + 5, 10, TFT_WHITE);
tft.fillCircle(centerX + 30, centerY + 5, 10, TFT_WHITE);
tft.drawArc(centerX, centerY + 30, 30, 20, 180, 360, TFT_WHITE);
break;

case ANGRY:
// Злость: наклоненные брови, маленькие глаза
tft.fillTriangle(centerX - 45, centerY - 20, centerX - 15, centerY - 10, centerX - 30, centerY + 10, TFT_WHITE);
tft.fillTriangle(centerX + 45, centerY - 20, centerX + 15, centerY - 10, centerX + 30, centerY + 10, TFT_WHITE);
tft.fillCircle(centerX - 25, centerY + 15, 8, TFT_WHITE);
tft.fillCircle(centerX + 25, centerY + 15, 8, TFT_WHITE);
break;

case NEUTRAL:
default:
// Нейтральное: обычные глаза и прямая линия
tft.fillCircle(centerX - 30, centerY, 12, TFT_WHITE);
tft.fillCircle(centerX + 30, centerY, 12, TFT_WHITE);
tft.drawLine(centerX - 20, centerY + 30, centerX + 20, centerY + 30, TFT_WHITE);
break;
}
}

// --- Вспомогательные функции движения ---
void moveToPose(int a1, int a2, int a3, int a4) {
servo1.write(constrain(a1 + offset[0], 0, 180));
servo2.write(constrain(a2 + offset[1], 0, 180));
servo3.write(constrain(a3 + offset[2], 0, 180));
servo4.write(constrain(a4 + offset[3], 0, 180));
}

void walkForward() {
moveToPose(110, 90, 70, 90); delay(200);
moveToPose(110, 105, 70, 75); delay(200);
moveToPose(90, 105, 90, 75); delay(200);
moveToPose(90, 90, 90, 90); delay(200);
}

void walkBackward() {
moveToPose(90, 110, 90, 70); delay(200);
moveToPose(75, 110, 105, 70); delay(200);
moveToPose(75, 90, 105, 90); delay(200);
moveToPose(90, 90, 90, 90); delay(200);
}

void turnLeft() {
moveToPose(65, 115, 65, 115); delay(400);
moveToPose(90, 90, 90, 90); delay(200);
}

void turnRight() {
moveToPose(115, 65, 115, 65); delay(400);
moveToPose(90, 90, 90, 90); delay(200);
}
